// Dual-send chokepoint: mirror a first-party analytics event into PostHog.
//
// CONTRACT — first-party /api/analytics stays the system of record. This module
// is the mirror half, and it is deliberately the ONLY place the docs site hands
// an event name to PostHog, for two reasons:
//
//   1. The 2026-07-07 "own it, don't rent it" decision (platform/docs/decisions)
//      rejected renting a product-analytics vendor. Mirroring keeps that intact:
//      losing PostHog tomorrow loses a read surface, not the data.
//   2. Event names are an analytics contract. Routing every send through here
//      means the first-party name and the PostHog name cannot drift apart —
//      callers pass one string and both sinks receive it.
//
// Every function is safe to call anywhere client-side. It never imports
// posthog-js: capturePostHog from lib/posthog-loader.ts is a no-op until the
// visitor allows analytics (lib/analytics-consent.ts); before that the
// cookieless client counts page views only. A missing NEXT_PUBLIC_POSTHOG_KEY (dev machine, CI,
// a fork) or a declined banner costs nothing and throws nothing.

import { capturePostHog } from "@/lib/posthog-loader";

type MirrorValue = string | number;

// capturePostHog takes string and number values. Booleans are sent as "true" or
// "false"; anything else (objects, null, undefined) is dropped, never sent.
function toMirrorProps(
	properties?: Record<string, unknown>,
): Record<string, MirrorValue> | undefined {
	if (!properties) return undefined;
	const out: Record<string, MirrorValue> = {};
	for (const [k, v] of Object.entries(properties)) {
		if (typeof v === "string" || typeof v === "number") out[k] = v;
		else if (typeof v === "boolean") out[k] = String(v);
	}
	return out;
}

/**
 * Mirror one already-sent first-party event into PostHog.
 *
 * Call it AFTER the first-party send, never instead of it, and never in a way
 * that lets a PostHog failure affect the caller — hence the swallowed catch.
 */
export function mirrorToPostHog(
	name: string,
	properties?: Record<string, unknown>,
): void {
	try {
		// Mirrors the first-party beacons' own guard: local runs must not pollute
		// the shared project with synthetic traffic.
		if (process.env.NODE_ENV === "development") return;
		capturePostHog(name, toMirrorProps(properties));
	} catch {
		// fail-open: analytics must never break the page
	}
}
